class Solution {
public:
    bool isConsecutive(vector<int>& nums) {
        // Your code goes here
        int min_el = INT_MAX;
        int max_el = 0;
        for(int i=0; i< nums.size(); i++){
            min_el = min(min_el, nums[i]);
            max_el = max(max_el, nums[i]);
        }
        if(nums.size()== (max_el- min_el)+1) return true;
        return false;

    }
};
