    bool isConsecutive(vector<int>& nums) {
        if (nums.empty()) return false;

        sort(nums.begin(), nums.end());

        for (int i = 1; i < nums.size(); i++) {
            if (nums[i] - nums[i-1] != 1) {
                return false;
            }
        }

        return true;
    }
};
