class Solution {
public:
    bool isConsecutive(vector<int>& nums) {
        int n=nums.size();
        int min=*min_element(nums.begin(),nums.end());
        unordered_set<int> st;
        for(auto it:nums){
            st.insert(it);
        }
        int index=0;
        while(index<n){
            if(st.find(min)==st.end()){
                return false;
            }
            min+=1;
            index++;
        }
        return true;
    }
};
